-- ============================================
-- AI Placement Platform Database Schema - COMPLETE CONSOLIDATED VERSION
-- PostgreSQL
-- Generated by consolidating: schema.sql, missing_tables.sql, advanced_proctoring_schema.sql, fix_interview_sessions.sql
-- ============================================


-- ============================================
-- USERS
-- ============================================
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role VARCHAR(20) NOT NULL DEFAULT 'student',
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    is_verified BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CHECK (role IN ('student', 'faculty', 'tpo', 'admin'))
);

CREATE INDEX idx_users_email ON users(email);


-- ============================================
-- USER PROFILES
-- ============================================
CREATE TABLE student_profiles (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL UNIQUE,
    roll_number VARCHAR(50),
    department VARCHAR(100) NOT NULL,
    cgpa FLOAT NOT NULL,
    graduation_year INTEGER NOT NULL,
    backlogs_count INTEGER NOT NULL,
    institution VARCHAR(200) NOT NULL,
    target_role VARCHAR(100),
    skills_json JSONB NOT NULL,
    phone_number VARCHAR(20),
    mobile_no VARCHAR(50),
    full_name VARCHAR(150),
    college_email_id VARCHAR(150),
    gender VARCHAR(50),
    date_of_birth VARCHAR(50),
    nationality VARCHAR(100),
    tenth_marks FLOAT,
    twelfth_marks FLOAT,
    bio TEXT,
    portfolio_data JSONB DEFAULT '{}' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE faculty_profiles (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL UNIQUE,
    department VARCHAR(100) NOT NULL,
    designation VARCHAR(100) NOT NULL,
    institution VARCHAR(200) NOT NULL,
    employee_id VARCHAR(50),
    bio TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE tpo_profiles (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL UNIQUE,
    institution VARCHAR(200) NOT NULL,
    designation VARCHAR(100) NOT NULL,
    contact_email VARCHAR(150),
    contact_phone VARCHAR(20),
    bio TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);


-- ============================================
-- REFRESH TOKENS
-- ============================================
CREATE TABLE refresh_tokens (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    token_hash TEXT NOT NULL,
    expires_at TIMESTAMP NOT NULL,
    is_revoked BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX idx_refresh_token_hash ON refresh_tokens(token_hash);


-- ============================================
-- USER RESUMES
-- ============================================
CREATE TABLE user_resumes (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    cv_name VARCHAR(200) NOT NULL,
    cv_type VARCHAR(100) NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    file_path VARCHAR(500) NOT NULL,
    file_size INTEGER NOT NULL,
    resume_text TEXT,
    parsed_skills JSONB NOT NULL DEFAULT '[]',
    parsed_projects JSONB NOT NULL DEFAULT '{}',
    uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX idx_user_resumes_user_id ON user_resumes(user_id);


-- ============================================
-- ASSESSMENT POLICIES & CONTEXTS
-- ============================================
CREATE TABLE assessment_policies (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    session_duration_minutes INTEGER NOT NULL,
    round_duration_minutes INTEGER NOT NULL,
    max_attempts INTEGER,
    resume_allowed BOOLEAN NOT NULL,
    exit_allowed BOOLEAN NOT NULL,
    progression_mode VARCHAR(20) NOT NULL,
    progression_config JSONB NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE assessment_contexts (
    id SERIAL PRIMARY KEY,
    mode VARCHAR(50) NOT NULL,
    purpose VARCHAR(100),
    created_by_id INTEGER,
    student_id INTEGER,
    company_name VARCHAR(200),
    target_role VARCHAR(100),
    jd_text TEXT,
    availability_start TIMESTAMP,
    availability_end TIMESTAMP,
    policy_id INTEGER NOT NULL,
    status VARCHAR(20) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP,
    FOREIGN KEY (created_by_id) REFERENCES users(id),
    FOREIGN KEY (student_id) REFERENCES users(id),
    FOREIGN KEY (policy_id) REFERENCES assessment_policies(id)
);

CREATE INDEX idx_assessment_contexts_student_id ON assessment_contexts(student_id);
CREATE INDEX idx_assessment_contexts_policy_id ON assessment_contexts(policy_id);


-- ============================================
-- ASSESSMENT SESSIONS
-- ============================================
CREATE TABLE assessment_sessions (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    context_id INTEGER,
    status VARCHAR(20) NOT NULL DEFAULT 'not_started'
        CHECK (status IN ('not_started','in_progress','completed','terminated','expired')),
    started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP,
    completed_at TIMESTAMP,
    total_score FLOAT DEFAULT 0,
    FOREIGN KEY (user_id) REFERENCES users(id),
    FOREIGN KEY (context_id) REFERENCES assessment_contexts(id)
);

CREATE UNIQUE INDEX one_active_session_per_user
ON assessment_sessions(user_id)
WHERE status='in_progress';

CREATE INDEX idx_assessment_sessions_context_id ON assessment_sessions(context_id);


-- ============================================
-- ASSESSMENT ROUNDS
-- ============================================
CREATE TABLE assessment_rounds (
    id SERIAL PRIMARY KEY,
    session_id INTEGER NOT NULL,
    round_type VARCHAR(20) NOT NULL
        CHECK (round_type IN ('aptitude','coding','interview')),
    status VARCHAR(20) NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending','active','completed','terminated','expired')),
    score FLOAT DEFAULT 0,
    max_questions INTEGER NOT NULL DEFAULT 20,
    started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP,
    completed_at TIMESTAMP,
    FOREIGN KEY (session_id)
        REFERENCES assessment_sessions(id) ON DELETE CASCADE
);

CREATE INDEX idx_round_session ON assessment_rounds(session_id);


-- ============================================
-- APTITUDE TOPICS
-- ============================================
CREATE TABLE aptitude_topics (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) UNIQUE NOT NULL
);


-- ============================================
-- APTITUDE QUESTIONS
-- ============================================
CREATE TABLE aptitude_questions (
    id SERIAL PRIMARY KEY,
    question_text TEXT NOT NULL,
    option_a TEXT NOT NULL,
    option_b TEXT NOT NULL,
    option_c TEXT NOT NULL,
    option_d TEXT NOT NULL,
    correct_option CHAR(1) NOT NULL
        CHECK (correct_option IN ('A','B','C','D')),
    difficulty VARCHAR(10) NOT NULL
        CHECK (difficulty IN ('easy','medium','hard')),
    topic_id INTEGER,
    version INTEGER NOT NULL DEFAULT 1,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_by INTEGER,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (topic_id) REFERENCES aptitude_topics(id),
    FOREIGN KEY (created_by) REFERENCES users(id)
);

CREATE INDEX idx_aptitude_difficulty ON aptitude_questions(difficulty);
CREATE INDEX idx_aptitude_topic ON aptitude_questions(topic_id);


-- ============================================
-- ADMIN QUESTION FEEDBACK
-- ============================================
CREATE TABLE admin_question_feedback (
    id SERIAL PRIMARY KEY,
    question_id INTEGER NOT NULL,
    admin_id INTEGER,
    action VARCHAR(20) NOT NULL
        CHECK (action IN ('approve','reject','review')),
    suggestion TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (question_id)
        REFERENCES aptitude_questions(id) ON DELETE CASCADE,
    FOREIGN KEY (admin_id)
        REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX idx_admin_qf_question_id ON admin_question_feedback(question_id);
CREATE INDEX idx_admin_qf_admin_id ON admin_question_feedback(admin_id);


-- ============================================
-- APTITUDE ATTEMPTS
-- ============================================
CREATE TABLE aptitude_attempts (
    id SERIAL PRIMARY KEY,
    round_id INTEGER NOT NULL,
    question_id INTEGER NOT NULL,
    attempt_number INTEGER NOT NULL,
    selected_option CHAR(1),
    is_correct BOOLEAN,
    response_time FLOAT,
    difficulty VARCHAR(10),
    reward FLOAT,
    attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (round_id)
        REFERENCES assessment_rounds(id) ON DELETE CASCADE,
    FOREIGN KEY (question_id)
        REFERENCES aptitude_questions(id),
    UNIQUE (round_id, attempt_number)
);

CREATE INDEX idx_aptitude_attempts_round ON aptitude_attempts(round_id);
CREATE INDEX idx_aptitude_attempts_question ON aptitude_attempts(question_id);


-- ============================================
-- RL SESSIONS (Reinforcement Learning for Adaptive Difficulty)
-- ============================================
CREATE TABLE rl_sessions (
    id SERIAL PRIMARY KEY,
    round_id INTEGER NOT NULL,
    step_number INTEGER NOT NULL,
    prev_difficulty VARCHAR(10)
        CHECK (prev_difficulty IN ('easy','medium','hard')),
    action_taken VARCHAR(10) NOT NULL
        CHECK (action_taken IN ('easy','medium','hard')),
    reward_received FLOAT,
    accuracy_so_far FLOAT,
    avg_response_time FLOAT,
    q_values JSONB,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (round_id)
        REFERENCES assessment_rounds(id) ON DELETE CASCADE,
    UNIQUE (round_id, step_number)
);

CREATE INDEX idx_rl_sessions_round ON rl_sessions(round_id);


-- ============================================
-- RL Q-TABLE (Global Q-Table for RL)
-- ============================================
CREATE TABLE rl_q_table (
    user_id INTEGER NOT NULL,
    state TEXT NOT NULL,
    action TEXT NOT NULL,
    q_value FLOAT DEFAULT 0.1,
    visit_count INTEGER DEFAULT 0,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, state, action),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX idx_rl_q_table_user ON rl_q_table(user_id);


-- ============================================
-- RL ATTEMPT LOG (Detailed RL Training Log)
-- ============================================
CREATE TABLE rl_attempt_log (
    id SERIAL PRIMARY KEY,
    user_id INTEGER,
    session_id INTEGER,
    question_id INTEGER,
    difficulty TEXT,
    state_before TEXT,
    action_taken TEXT,
    reward FLOAT,
    state_after TEXT,
    response_time FLOAT,
    is_correct BOOLEAN,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id),
    FOREIGN KEY (session_id) REFERENCES assessment_sessions(id),
    FOREIGN KEY (question_id) REFERENCES aptitude_questions(id)
);

CREATE INDEX idx_rl_attempt_log_user ON rl_attempt_log(user_id);
CREATE INDEX idx_rl_attempt_log_session ON rl_attempt_log(session_id);


-- ============================================
-- CODING PROBLEMS
-- ============================================
CREATE TABLE coding_problems (
