    input_format TEXT,
    output_format TEXT,
    constraints TEXT,
    created_by INTEGER,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (created_by) REFERENCES users(id)
);

CREATE INDEX idx_coding_problems_difficulty ON coding_problems(difficulty);
CREATE INDEX idx_coding_problems_created_by ON coding_problems(created_by);


-- ============================================
-- CODING TEST CASES
-- ============================================
CREATE TABLE coding_test_cases (
    id SERIAL PRIMARY KEY,
    problem_id INTEGER NOT NULL,
    input_data TEXT NOT NULL,
    expected_output TEXT NOT NULL,
    is_hidden BOOLEAN DEFAULT TRUE,
    case_order INTEGER NOT NULL DEFAULT 0,
    explanation TEXT,
    FOREIGN KEY (problem_id)
        REFERENCES coding_problems(id) ON DELETE CASCADE
);

CREATE INDEX idx_coding_test_cases_problem ON coding_test_cases(problem_id);


-- ============================================
-- SESSION PROBLEMS (assigned coding problems per round)
-- ============================================
CREATE TABLE session_problems (
