CREATE INDEX idx_session_problems_round ON session_problems(round_id);
CREATE INDEX idx_session_problems_problem ON session_problems(problem_id);


-- ============================================
-- CODING SUBMISSIONS
-- ============================================
CREATE TABLE coding_submissions (
