);

CREATE INDEX idx_coding_submission_round ON coding_submissions(round_id);
CREATE INDEX idx_coding_submission_problem ON coding_submissions(problem_id);
CREATE INDEX idx_judge0_token ON coding_submissions(judge0_token);


-- ============================================
-- APPROVED QUESTION POOLS
-- ============================================
CREATE TABLE approved_question_pools (
    id SERIAL PRIMARY KEY,
    session_id INTEGER NOT NULL,
    extracted_skills JSONB NOT NULL DEFAULT '[]',
