-- ============================================
-- PROCTORING VIOLATIONS (Interview-specific)
-- ============================================
CREATE TABLE proctoring_violations (
    id SERIAL PRIMARY KEY,
    session_id INTEGER NOT NULL REFERENCES interview_sessions(id) ON DELETE CASCADE,
